"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["33568"],{88532(e,a,t){t.r(a),t.d(a,{metadata:()=>r,default:()=>l,frontMatter:()=>c,contentTitle:()=>d,toc:()=>h,assets:()=>p});var r=JSON.parse('{"id":"nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-process","title":"Adjudicator: act on a case","description":"Approves, rejects, queries or forwards a PMJAY case in the State Health Agency\'s Transaction Management System, as the role that currently holds it.","source":"@site/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-process.mdx","sourceDirName":"nhcx/v1/api/adjudicator/endpoints","slug":"/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-process","permalink":"/docs/pr-12/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-process","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Adjudicator: act on a case","sidebar_label":"Adjudicator: act on a case","sidebar_class_name":"api-method api-method--post","description":"Approves, rejects, queries or forwards a PMJAY case in the State Health Agency\'s Transaction Management System, as the role that currently holds it.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-adjudicator.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Adjudicator: role for a case","permalink":"/docs/pr-12/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-adjudicator-role"},"next":{"title":"Dummy payer, act on a request","permalink":"/docs/pr-12/docs/nhcx/v1/api/adjudicator/endpoints/adjudicator-dummy-payer-process-request"}}'),s=t(62540),n=t(43023),i=t(44136),o=JSON.parse('{"id":"adjudicator_adjudicator_process","module":"PMJAY adjudicator","moduleId":"adjudicator","kind":"operation","method":"POST","path":"/pmjay/hcx/nhcxpayerservice/wrapper/process/case","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer","description":"Sandbox, Dummy payer."}],"summary":"Adjudicator: act on a case","description":"Approves, rejects, queries or forwards a PMJAY case in the State Health Agency\'s Transaction Management System, as the role that currently holds it.\\n\\n### Business purpose\\n\\nThis is the action half of the NHCX Payer Service. A PMJAY case sits at `request.initiated` until a role acts on it here, so in the sandbox this call is what makes a case move. A scheme payer building its own side can copy the shape: the exchange carries messages, the queue decides cases, and a case ID the payer issues joins the two.\\n\\n### When to use\\n\\nAfter `Adjudicator: role for a case` has named the role that holds the case, with the action spelled exactly as that role takes it:\\n\\n- `PPD-Trust`, pre-authorisation: `Approve`, `Reject`, `Query`, with `usecase` `PREAUTH`.\\n- `CEX-Trust`, first claim desk: `Forward`, with `usecase` `CLAIM`.\\n- `CPD-Trust`, second claim desk: `cpdApprove`, `cpdReject`, `Pending`, with `usecase` `CLAIM`.\\n- Medical Audit Committee: `Approve`, `Reject`, `iQuery`, with `usecase` `Medical Audit Committee`.\\n- `ACO-Trust` and `SHA-Trust`: `Approve`, `Reject`, `Pending`, with `usecase` `CLAIM`.\\n- Claim Review Committee: `Approve`, `Reject`, `Pending`, with `usecase` `Claim Review Committee`.\\n\\n### Preconditions\\n\\n- `casenumber` is the scheme\'s case ID, not the hospital\'s claim number.\\n- `action` is spelled exactly as the holding role takes it. It is case-sensitive.\\n- `receivercode` is the payer\'s registry ID and `sendercode` the provider\'s participant code, both without the `@hcx` suffix.\\n- `memberid` names the beneficiary, and `remarks` is free text the desk records.\\n- `correlationid` is a fresh UUID for every call.\\n- An ordinary ABDM session token on `bearer_auth`.\\n\\n### Postconditions\\n\\nActing on the case makes the scheme issue its verdict, which reaches the provider over NHCX as an ordinary `ClaimResponse` on the original request\'s correlation ID. The desk call and that callback are two halves of one step, correlated by the case rather than by this call\'s own correlation ID. An action refused for the current role means the role has moved, or was never what you assumed.\\n\\n### Common mistakes\\n\\n- Sending `Approve` to `CPD-Trust`, which takes `cpdApprove` and `cpdReject`.\\n- Sending `CLAIM` as the `usecase` at either committee, which takes its full name with spaces.\\n- Assuming a case walks all six claim roles. On the recorded sandbox run neither committee held the case.\\n- Reusing a correlation ID across desk calls.\\n- Raising a second request on a case while the first is still queued, which the sandbox refused with `PAYR-1322`.\\n\\n### Best practices\\n\\n- Read the role immediately before every action.\\n- Retry shortly on `Event Meta Log not found for correlationId`, which means the exchange has not finished delivering the request, and on `Case not found for caseId`, which means the case is mid-filing.\\n- Hold both threads in a test harness: this call, and the callback it causes.\\n- Report the scheme\'s pace rather than asserting it. An enhancement may be answered `queued` again and decided minutes later.\\n\\n### Related scenario\\n\\nOn the recorded sandbox run the pre-authorisation was approved as `PPD-Trust` with `Approve` and `usecase` `PREAUTH`. After the claim was raised it was forwarded by `CEX-Trust`, approved by `CPD-Trust` as `cpdApprove`, then by `ACO-Trust` and `SHA-Trust`, each time after reading the role again and with a new correlation ID. The role lookup then answered with no role, and the approval arrived on the claim\'s own callback.\\n\\n### Specification\\n\\nChapter [PMJAY adjudication APIs](/docs/nhcx/v1/roles/provider/pmjay-adjudication-apis) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"casenumber","type":"string","required":false,"description":"","encrypted":false},{"name":"action","type":"string","required":false,"description":"","encrypted":false},{"name":"receivercode","type":"string","required":false,"description":"","encrypted":false},{"name":"usecase","type":"string","required":false,"description":"","encrypted":false},{"name":"correlationid","type":"string","required":false,"description":"","encrypted":false},{"name":"sendercode","type":"string","required":false,"description":"","encrypted":false},{"name":"memberid","type":"string","required":false,"description":"","encrypted":false},{"name":"remarks","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"casenumber":"<case number>","action":"Approve","receivercode":"<payer code>","usecase":"PREAUTH","correlationid":"<correlation id>","sendercode":"<participant code>","memberid":"<member id>","remarks":"ok"},"responses":[{"status":"200","description":"Acting on the case makes the scheme issue its verdict, which reaches the provider over NHCX as an ordinary `ClaimResponse` on the original request\'s correlation ID.","example":{"status":"success","message":"Case processed"}}],"tag":"PMJAY adjudicator","tagDescription":"A PMJAY case is not decided over NHCX.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/pmjay/hcx/nhcxpayerservice/wrapper/process/case \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"casenumber\\": \\"<case number>\\",\\n  \\"action\\": \\"Approve\\",\\n  \\"receivercode\\": \\"<payer code>\\",\\n  \\"usecase\\": \\"PREAUTH\\",\\n  \\"correlationid\\": \\"<correlation id>\\",\\n  \\"sendercode\\": \\"<participant code>\\",\\n  \\"memberid\\": \\"<member id>\\",\\n  \\"remarks\\": \\"ok\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/pmjay/hcx/nhcxpayerservice/wrapper/process/case \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"casenumber\\": \\"<case number>\\",\\n  \\"action\\": \\"Approve\\",\\n  \\"receivercode\\": \\"<payer code>\\",\\n  \\"usecase\\": \\"PREAUTH\\",\\n  \\"correlationid\\": \\"<correlation id>\\",\\n  \\"sendercode\\": \\"<participant code>\\",\\n  \\"memberid\\": \\"<member id>\\",\\n  \\"remarks\\": \\"ok\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/pmjay/hcx/nhcxpayerservice/wrapper/process/case\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"casenumber\\": \\"<case number>\\",\\n        \\"action\\": \\"Approve\\",\\n        \\"receivercode\\": \\"<payer code>\\",\\n        \\"usecase\\": \\"PREAUTH\\",\\n        \\"correlationid\\": \\"<correlation id>\\",\\n        \\"sendercode\\": \\"<participant code>\\",\\n        \\"memberid\\": \\"<member id>\\",\\n        \\"remarks\\": \\"ok\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/dummyhcxpayer/pmjay/hcx/nhcxpayerservice/wrapper/process/case\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"casenumber\\": \\"<case number>\\",\\n    \\"action\\": \\"Approve\\",\\n    \\"receivercode\\": \\"<payer code>\\",\\n    \\"usecase\\": \\"PREAUTH\\",\\n    \\"correlationid\\": \\"<correlation id>\\",\\n    \\"sendercode\\": \\"<participant code>\\",\\n    \\"memberid\\": \\"<member id>\\",\\n    \\"remarks\\": \\"ok\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"Adjudicator: act on a case",sidebar_label:"Adjudicator: act on a case",sidebar_class_name:"api-method api-method--post",description:"Approves, rejects, queries or forwards a PMJAY case in the State Health Agency's Transaction Management System, as the role that currently holds it.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-adjudicator.yaml",generated:!0},d,p={},h=[];function u(e){return(0,s.jsx)(i.A,{operation:o})}function l(e={}){let{wrapper:a}={...(0,n.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}}}]);